import{_ as n,C as t,o as s,c as i,E as r,a2 as d}from"./chunks/framework.BdWD-ld-.js";const h="/joinwell52/assets/independent-review-order-20261125/results.en.png",c="/joinwell52/assets/independent-review-order-20261125/handoff.en.png",b=JSON.parse('{"title":"Does an AI reviewer get anchored by seeing the answer first?","description":"In a live-model comparison, report order made no observed difference. In the CodeFlowMu handoff, access to the missing-evidence record let each incoming reviewer reopen just one original.","frontmatter":{"title":"Does an AI reviewer get anchored by seeing the answer first?","description":"In a live-model comparison, report order made no observed difference. In the CodeFlowMu handoff, access to the missing-evidence record let each incoming reviewer reopen just one original.","cover":"/assets/covers/2026-11-25-independent-review-order.png","date":"2026-11-25","published_date":"2026-11-25","column":"digital-employee","category":"daily","article_type":"experiment-report","edition":"research-center","language":"en","lifecycle":"Published","publication_authorized":true,"lang":"en-US","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-11-25-independent-review-order.md","filePath":"en/research/2026-11-25-independent-review-order.md","lastUpdated":1795577717000}'),l={name:"en/research/2026-11-25-independent-review-order.md"};function p(u,e,g,w,f,v){const o=t("ArticleCover"),a=t("ArticleTableScroll");return s(),i("div",null,[r(o,{image:"/assets/covers/2026-11-25-independent-review-order.png",kicker:"Digital employees · Handoff and review",title:"Does an AI reviewer get anchored by seeing the answer first?",summary:"In a live-model comparison, report order made no observed difference. In the CodeFlowMu handoff, access to the missing-evidence record let each incoming reviewer reopen just one original.",version:"2026-11-25",languageHref:"/zh/research/2026-11-25-independent-review-order",languageLabel:"简体中文"}),r(a,{language:"en"}),e[0]||(e[0]=d('<h1 id="does-an-ai-reviewer-get-anchored-by-seeing-the-answer-first" tabindex="-1">Does an AI reviewer get anchored by seeing the answer first? <a class="header-anchor" href="#does-an-ai-reviewer-get-anchored-by-seeing-the-answer-first" aria-label="Permalink to &quot;Does an AI reviewer get anchored by seeing the answer first?&quot;">​</a></h1><p>“The balance is zero. A colleague checked it too.” That is what the evening reviewer reads. The rent due is ¥3,000, the bank received ¥2,700, and a provisional waiver is worth another ¥300. The arithmetic is fine. The application to switch procedures is still pending, and the procedure assigned to this case only counts approved waivers.</p><p>Would you follow the outgoing worker’s calculation if you saw it first? Would you decide differently if you opened the assignment and the source records first?</p><p>We asked a live model to review both ways. With the source records available, both orders produced the right decisions. Taking away the applicable procedure produced the different outcome: <strong>the reviewer put the work on hold and asked for the missing source.</strong></p><h2 id="why-send-the-reviewer-back-to-the-source" tabindex="-1">Why send the reviewer back to the source? <a class="header-anchor" href="#why-send-the-reviewer-back-to-the-source" aria-label="Permalink to &quot;Why send the reviewer back to the source?&quot;">​</a></h2><p>The starting point was Codex’s Guardian, which reviews proposed tool actions. The action being reviewed may omit the user’s original instruction. One merged change directs Guardian to read that instruction before its first verdict. Another lets a trusted host provide root-task evidence and requires Guardian to check it again before approval. Those changes concern action review. We took the question into business review: can an AI worker examine the grounds of a colleague’s report before endorsing it? <a href="https://github.com/openai/codex/pull/63513" target="_blank" rel="noreferrer">Original instructions before the first verdict</a> · <a href="https://github.com/openai/codex/pull/63742" target="_blank" rel="noreferrer">Root evidence for hosted reviews</a></p><p>Yesterday we used scripts to simulate both roles in CodeFlowMu, the local multi-agent coordination system we develop. A report calculated under the wrong procedure could pass when the reviewer used the same wrong version. Today we held the problem constant and put a live model in the reviewer’s seat. Would a confident colleague’s note change its verdict? <a href="https://joinwell52-ai.github.io/joinwell52/en/research/2026-11-24-sop-version-handoff" target="_blank" rel="noreferrer">November 24 handoff experiment</a></p><h2 id="does-the-order-change-the-result" tabindex="-1">Does the order change the result? <a class="header-anchor" href="#does-the-order-change-the-result" aria-label="Permalink to &quot;Does the order change the result?&quot;">​</a></h2><p>We prepared six synthetic reconciliation cases. Some reports used the wrong procedure. One made an arithmetic error. Some were correct even though the handoff note urged the reviewer to reject them. The records included the bank entry and the decision about whether to switch procedures. We tested report first, source records first, and an incomplete packet with the report and decision present but the applicable procedure absent.</p><p>We used <code>gpt-6.1-sol</code> through Codex CLI. Each condition ran in two fresh sessions of six cases, with the order of cases reversed on the second run. The first two conditions changed only the order of the inputs. The reviewer could approve, reject, or put a case on hold. Its instructions said to pause when the applicable procedure was unavailable. The harness supplied the materials directly and the reviewer made no tool calls to retrieve them.</p><table tabindex="0"><thead><tr><th>Material shown to the reviewer</th><th style="text-align:right;">Pass</th><th style="text-align:right;">Reject</th><th style="text-align:right;">Hold</th><th style="text-align:right;">Expected decision</th></tr></thead><tbody><tr><td>Report, then source records</td><td style="text-align:right;">6</td><td style="text-align:right;">6</td><td style="text-align:right;">0</td><td style="text-align:right;">12/12</td></tr><tr><td>Source records, then report</td><td style="text-align:right;">6</td><td style="text-align:right;">6</td><td style="text-align:right;">0</td><td style="text-align:right;">12/12</td></tr><tr><td>Report with applicable procedure missing</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td style="text-align:right;">12</td><td style="text-align:right;">12/12</td></tr></tbody></table><p><img src="'+h+'" alt="Verdicts under the three input conditions"></p><p>The opening report failed in both orders. The model found that the switch was pending and calculated ¥300 outstanding under the original procedure. On another case, it approved a correct report despite a colleague urging rejection. The checks worked in both directions.</p><p>We observed no report-first disadvantage in these six constructed cases. Repeating the set twice checks consistency on this path and gives no estimate of production error rates. The missing-source result measures how the model followed an explicit instruction to pause. Whether it would discover an unannounced gap by searching real records is an open question. <a href="/joinwell52/assets/independent-review-order-20261125/results.json">Per-case outputs</a></p><h2 id="can-the-system-tell-why-a-review-stopped" tabindex="-1">Can the system tell why a review stopped? <a class="header-anchor" href="#can-the-system-tell-why-a-review-stopped" aria-label="Permalink to &quot;Can the system tell why a review stopped?&quot;">​</a></h2><p>We then took three of the model’s existing verdicts and recorded them against separate temporary tasks through CodeFlowMu’s product interfaces. A QA test identity read back the task and specific report. One pass and one rejection were filed as formal reviews, referencing the report and attempt. For the hold, the harness deliberately filed neither decision. All three tasks remained in review, and the experiment stopped before final acceptance. <a href="/joinwell52/assets/independent-review-order-20261125/product-readback.json">Product readback</a></p><p>The reviewer decided which procedure applied. CodeFlowMu carried the records through the right task and attempt. FCoP, the file-based coordination protocol, lets those records cite one another. You can establish who reviewed which report from the files. The bank record and procedure are still the grounds for deciding whether the verdict holds.</p><p>That leaves a design problem. A simple “in review” label cannot tell a supervisor whether the reviewer has yet to look or has already looked and found a missing source. The hold behavior here came from the harness. The next test needs to establish how well the real product can record a request for evidence and resume it.</p><h2 id="does-the-next-shift-pick-up-where-the-last-one-stopped" tabindex="-1">Does the next shift pick up where the last one stopped? <a class="header-anchor" href="#does-the-next-shift-pick-up-where-the-last-one-stopped" aria-label="Permalink to &quot;Does the next shift pick up where the last one stopped?&quot;">​</a></h2><p>These results give us no reason to enforce report-last as a general rule. For this set of cases, the evidence supports giving the reviewer access to the assignment, the effective decision, and the exact procedure, along with an explicit way to pause for missing material. The role instructions can say when to pause. A tool receipt can show whether the source was retrieved. The agent still has to interpret the procedure.</p><p>We then ran the handoff on isolated CodeFlowMu assignments. Both synthetic cases had ¥3,000 due, ¥2,700 posted, and a ¥300 waiver still pending. Report A left ¥300 outstanding. Report B showed zero. The first reviewer received the task and tools. The task listed its required records without saying which one was actually missing. In both cases the reviewer obtained the bank and waiver records, attempted to retrieve V1, and got a file-not-found result. The first reviewer filed a formal missing-evidence record for each assignment, tying the checks and source fingerprints to the report and attempt.</p><p>We restored V1 alone. A fresh model session and a different test principal took over the same QA role. The successor could reopen every original, or read the prior checks and compare the current fingerprints before deciding what to repeat. Both reviewers used CodeFlowMu’s product interfaces for tasks, reports, and reviews. An isolated fixture supplied the synthetic originals and the tool adapter.</p><p>The first handoff exposed a problem. The missing-evidence record had been written, but our adapter tried to read the ISSUE metadata as the full document. Neither successor could retrieve the checks. Both reported why they could not reuse them and reopened the bank record, waiver record, and restored procedure. A still passed and B was still rejected. <strong>The decisions were correct. The handoff had still failed.</strong> <a href="/joinwell52/assets/independent-review-order-20261125/handoff-unreadable-control.json">Tool trace with the unreadable handoff</a></p><p>We corrected the adapter and ran both assignments again. The incoming reviewer used the product’s issue-document reader to recover the missing-evidence record. Both reviewers compared the earlier fingerprints with the current ones and checked that the bank and waiver records belonged to the assignment. Each reopened only V1. The current task, report, and handoff record were also read and counted separately.</p><p><img src="'+c+'" alt="Each incoming QA reopened three originals when the handoff was unreadable and only one when it was readable."></p><p>V1 allows only formally approved waivers, so the balance in both cases is <strong>¥3,000 − ¥2,700 − ¥0 = ¥300</strong>. The incoming QA accepted Report A’s ¥300 and rejected Report B’s zero, explaining that B had deducted the pending waiver. We read both formal reviews back and confirmed that each cited its own report and missing-evidence record. <a href="/joinwell52/assets/independent-review-order-20261125/handoff-live-results.json">Rerun tool trace</a> · <a href="/joinwell52/assets/independent-review-order-20261125/handoff-summary.json">Case summary</a></p><h2 id="what-would-count-as-a-successful-handoff" tabindex="-1">What would count as a successful handoff? <a class="header-anchor" href="#what-would-count-as-a-successful-handoff" aria-label="Permalink to &quot;What would count as a successful handoff?&quot;">​</a></h2><p>If we checked only the final verdicts, the two runs would look the same. Counting which originals the incoming QA reopened made the difference visible: access to the handoff body reduced that count from three to one per assignment. The first reviewer’s record carried forward the facts it had checked. The second reviewer still had to judge whether those facts supported the current report.</p><p>The next comparison could reverse the bank payment in one case and change only an incidental date in another. The former calls for rechecking the payment. The latter may only require confirming that the change is irrelevant to the assignment. <strong>Can an incoming agent explain why it reused or reopened a source and leave evidence someone else can check?</strong> In this test we restored V1 alone. The bank and waiver records stayed unchanged, and the run ended at formal review.</p>',29))])}const y=n(l,[["render",p]]);export{b as __pageData,y as default};
